    "subtitle": "MAP này tập trung giải mã mức độ phù hợp của bạn với hai cơ chế thu nhập chủ đạo: thu nhập có tính ổn định, tương đối dự đoán được theo thời gian và thu nhập biến động dựa trên hiệu suất, kết quả công việc, doanh số, lợi nhuận hoặc những giá trị kinh tế thực tế được tạo ra; thông qua việc phân tích nhu cầu an toàn tài chính, động lực thành tựu, khả năng chịu đựng biến động, phong cách làm việc, mức độ tự chủ, năng lực tạo kết quả, khả năng kiểm soát đầu ra và điều kiện kinh tế cá nhân; từ đó phân biệt sự yêu thích ổn định với khả năng duy trì hiệu quả trong môi trường ổn định, phân biệt khát vọng thu nhập cao với năng lực quản trị rủi ro của thu nhập biến động, đồng thời xác định những điều kiện cần thiết để lựa chọn cơ chế trả công phù hợp; MAP không mặc định thu nhập ổn định là an toàn tuyệt đối hoặc thu nhập theo kết quả luôn có tiềm năng cao hơn, mà hướng đến việc xây dựng cấu trúc thu nhập dựa trên bằng chứng, cân bằng giữa sự chắc chắn của dòng tiền, khả năng gia tăng thu nhập, mức độ kiểm soát, chất lượng cuộc sống và tính bền vững lâu dài.",
