    "subtitle": "MAP này tập trung giải mã và xây dựng hệ thống quản trị rủi ro cá nhân toàn diện, phù hợp với đặc điểm tư duy, năng lực ra quyết định, khả năng chịu đựng bất định, điều kiện nguồn lực, mục tiêu phát triển và những trách nhiệm quan trọng của bạn; thông qua việc tổng hợp cách bạn nhận diện nguy cơ, đánh giá xác suất và hậu quả, xác định mức rủi ro có thể chấp nhận, lựa chọn biện pháp phòng ngừa, xây dựng phương án dự phòng, bảo vệ nguồn lực cốt lõi, hành động trong khủng hoảng và phục hồi sau biến cố; từ đó làm rõ sự khác biệt giữa quản trị rủi ro chủ động và phản ứng khi sự cố đã xảy ra, giữa hệ thống bảo vệ phù hợp với việc phòng thủ quá mức, giữa chấp nhận rủi ro có kiểm soát và hành động chủ quan, giữa quản trị từng nguy cơ riêng lẻ và kiểm soát tác động tích lũy của nhiều rủi ro, giữa sở hữu kế hoạch dự phòng và duy trì một hệ thống có thể vận hành thực tế; đồng thời đánh giá khả năng thiết lập nguyên tắc ra quyết định, xác định giới hạn tổn thất, phân bổ nguồn lực bảo vệ, lựa chọn chỉ báo cảnh báo sớm, thiết kế cơ chế kích hoạt ứng phó, theo dõi rủi ro còn lại và điều chỉnh phương án theo từng giai đoạn cuộc sống; nhằm giúp bạn hình thành một hệ thống quản trị rủi ro cá nhân đơn giản, rõ ràng, có thứ tự ưu tiên, có tiêu chí đo lường và có khả năng duy trì lâu dài; qua đó bảo vệ những điều quan trọng, giảm thiểu tổn thất có thể phòng tránh, chủ động trước bất định, duy trì năng lực hành động khi khủng hoảng xảy ra và tạo điều kiện theo đuổi cơ hội phát triển mà không bị nỗi sợ rủi ro chi phối.",
