    "subtitle": "MAP này tập trung giải mã khoảng cách giữa năng lực bạn đang thể hiện trong thực tế và mức năng lực cao hơn mà bạn có cơ sở để phát triển trong những điều kiện phù hợp; thông qua việc phân tích kiến thức, kỹ năng, tư duy, kinh nghiệm, động lực, thói quen, khả năng học hỏi, mức độ tự tin, môi trường, cơ hội thực hành và những nguồn lực hỗ trợ hiện có. Trọng tâm của MAP là phân biệt năng lực đã được chứng minh với năng lực chưa có điều kiện thể hiện, tiềm năng có bằng chứng với kỳ vọng chủ quan, giới hạn kỹ năng với giới hạn môi trường, sự thiếu hụt nguồn lực với những rào cản tâm lý, và năng lực chưa được khai thác với những khả năng vẫn cần được xây dựng từ đầu. MAP đồng thời làm rõ những nguyên nhân khiến một người sở hữu kiến thức nhưng chưa chuyển hóa thành kết quả, có khả năng học nhanh nhưng thiếu cơ hội thử sức, có năng lực chuyên môn nhưng chưa được giao trách nhiệm tương xứng, hoặc đạt hiệu suất thấp vì phương pháp, môi trường và hệ thống hỗ trợ chưa phù hợp. Thay vì mặc định rằng mỗi người đều sở hữu một mức tiềm năng tối đa cố định có thể xác định trước, MAP hướng đến việc nhận diện những khả năng phát triển có căn cứ thông qua kết quả thực tế, tốc độ học hỏi, mức cải thiện sau phản hồi, khả năng thích nghi và hiệu suất trong những điều kiện khác nhau. Từ đó, MAP giúp xác định khoảng cách phát triển quan trọng nhất, phân tích nguyên nhân, nhận diện điểm nghẽn có tác động lớn, lựa chọn đòn bẩy phù hợp và thiết kế các thử nghiệm nhằm kiểm chứng khả năng tiến bộ; qua đó xây dựng lộ trình thu hẹp khoảng cách giữa những gì bạn đang làm được và những gì bạn có thể từng bước đạt được bằng sự phát triển năng lực thực chất.",
