    "subtitle": "MAP này tập trung giải mã và xác định những năng lực có tính đòn bẩy cao, tức những năng lực mà khi được nâng cấp có thể tạo ra sự cải thiện đồng thời trong nhiều lĩnh vực của cuộc sống, công việc, học tập, các mối quan hệ và hành trình phát triển cá nhân; thông qua việc phân tích cấu trúc năng lực hiện tại, mối liên hệ giữa các kỹ năng, khả năng chuyển giao kiến thức, mức độ ảnh hưởng của từng năng lực đến kết quả thực tế và những điều kiện cần thiết để hiệu ứng phát triển lan tỏa xuất hiện. Trọng tâm của MAP là phân biệt năng lực chuyên biệt với năng lực nền tảng, kỹ năng tạo kết quả trực tiếp với kỹ năng hỗ trợ nhiều kết quả, năng lực nổi bật với năng lực có tác động hệ thống, và khả năng cải thiện một lĩnh vực với khả năng tạo ra hiệu ứng cộng hưởng giữa nhiều lĩnh vực. MAP đặc biệt xem xét những nhóm năng lực có thể đóng vai trò đòn bẩy như tư duy phân tích, học hỏi, giao tiếp, quản trị cảm xúc, tự quản lý, ra quyết định, giải quyết vấn đề, thích nghi, hợp tác và tổ chức thực thi; tuy nhiên, không mặc định rằng một năng lực bất kỳ luôn là đòn bẩy quan trọng nhất đối với mọi người. Giá trị đòn bẩy cần được xác định dựa trên nhu cầu thực tế, những điểm nghẽn hiện tại, mức độ phụ thuộc giữa các lĩnh vực, khả năng chuyển giao và bằng chứng cải thiện sau khi năng lực được nâng cấp. Từ đó, MAP giúp bạn nhận diện những năng lực đang giữ vai trò trung tâm trong hệ thống phát triển, đánh giá tác động trực tiếp và gián tiếp của từng năng lực, xác định thứ tự ưu tiên đầu tư, lựa chọn phương pháp rèn luyện và kiểm chứng mức độ lan tỏa của kết quả; qua đó xây dựng chiến lược phát triển tập trung, trong đó việc nâng cấp một số năng lực then chốt có thể đồng thời cải thiện nhiều hoạt động, giảm những điểm nghẽn lặp lại, nâng cao hiệu quả sử dụng nguồn lực và tạo nền tảng cho những bước tiến lớn hơn.",
