    "groupTitle": "TIỀM NĂNG & ĐÒN BẨY PHÁT TRIỂN",
    "title": "TIỀM NĂNG NÀO CHỈ XUẤT HIỆN KHI BẠN BƯỚC SANG MỘT CẤP ĐỘ TRÁCH NHIỆM LỚN HƠN?",
    "subtitle": "MAP này tập trung giải mã những năng lực, phẩm chất, nguồn lực nội tại và khả năng phát triển có thể chưa được thể hiện đầy đủ trong phạm vi trách nhiệm hiện tại nhưng có cơ hội bộc lộ, được rèn luyện và phát triển mạnh mẽ hơn khi bạn đảm nhận những vai trò có mức độ tự chủ, ảnh hưởng, độ phức tạp và trách nhiệm cao hơn. Trọng tâm của MAP là xác định những tiềm năng chưa được thử thách đúng mức, những năng lực chỉ có thể được kiểm chứng khi đối diện với yêu cầu mới, và những điều kiện cần thiết để chuyển từ thực hiện nhiệm vụ cá nhân sang quản lý kết quả, điều phối nguồn lực, dẫn dắt con người, chịu trách nhiệm về quyết định hoặc tạo tác động ở quy mô lớn hơn. MAP phân biệt trách nhiệm với quyền lực, chức danh với năng lực thực tế, khối lượng công việc với cấp độ trách nhiệm, khả năng thực hiện tốt nhiệm vụ hiện tại với năng lực đảm nhận vai trò cao hơn, và tiềm năng phát triển với mức độ sẵn sàng thực tế. Đặc biệt, MAP xem xét những năng lực có thể được kích hoạt hoặc phát triển thông qua thử thách mới như tư duy chiến lược, ra quyết định trong điều kiện không chắc chắn, quản trị rủi ro, phân bổ nguồn lực, giao việc, xây dựng hệ thống, giải quyết xung đột, chịu trách nhiệm về kết quả tập thể và duy trì sự ổn định trước áp lực. MAP đồng thời phân tích sự chuyển đổi từ tư duy người thực hiện sang người chịu trách nhiệm cuối cùng, từ tối ưu hiệu suất cá nhân sang tạo điều kiện để người khác đạt kết quả, và từ giải quyết vấn đề trước mắt sang dự báo những hệ quả dài hạn. Tuy nhiên, MAP không mặc định rằng mọi người đều cần thăng chức, quản lý đội nhóm hoặc mở rộng quyền lực để phát triển. Trách nhiệm lớn hơn cũng có thể xuất hiện trong chuyên môn sâu, quản lý dự án, kinh doanh độc lập, chăm sóc gia đình, dẫn dắt cộng đồng hoặc những quyết định cá nhân có tác động lâu dài. MAP cũng không xem việc chịu áp lực quá mức là bằng chứng của trưởng thành; một bước tiến phù hợp cần đi kèm năng lực, quyền hạn tương xứng, nguồn lực hỗ trợ và giới hạn trách nhiệm rõ ràng. Từ đó, MAP giúp bạn nhận diện những tiềm năng chưa được khai thác do phạm vi vai trò còn hạn chế, đánh giá khoảng cách giữa năng lực hiện tại và yêu cầu trách nhiệm mới, xác định những kỹ năng cần chuẩn bị, lựa chọn thử thách có mức độ tăng dần và kiểm chứng khả năng đảm nhận vai trò lớn hơn; qua đó xây dựng lộ trình phát triển trách nhiệm có chiến lược, giúp chuyển hóa tiềm năng thành năng lực thực tế và mở rộng phạm vi đóng góp một cách bền vững.",
