    "title": "BẠN CẦN THÊM ĐIỀU GÌ VÀ CẦN BỚT ĐIỀU GÌ ĐỂ SỐNG TỐT HƠN?",
    "subtitle": "MAP này tập trung giải mã những yếu tố cần được bổ sung, duy trì, giảm bớt hoặc loại bỏ để nâng cao chất lượng cuộc sống theo hướng phù hợp với nhu cầu, giá trị, hoàn cảnh và nguồn lực thực tế của bạn. Trọng tâm của MAP là xác định cuộc sống hiện tại đang thiếu những điều gì thực sự quan trọng, đang dư thừa những yếu tố nào gây tiêu hao nguồn lực, những gì cần được bảo vệ và những gì không còn phù hợp để tiếp tục duy trì. MAP phân biệt nhu cầu thiết yếu với mong muốn nhất thời, bổ sung có giá trị với tích lũy không cần thiết, giảm bớt để giải phóng nguồn lực với từ bỏ trách nhiệm, đơn giản hóa cuộc sống với tự giới hạn cơ hội phát triển, và thay đổi thực chất với những điều chỉnh chỉ tạo cảm giác dễ chịu tạm thời. Đặc biệt, MAP xem xét hai hướng cải thiện có tính bổ trợ: tăng cường những yếu tố đang thiếu như giấc ngủ, sức khỏe, năng lượng, thời gian tự chủ, kết nối chân thành, cảm giác an toàn, niềm vui, kiến thức, cơ hội phát triển và ý nghĩa sống; đồng thời giảm bớt những yếu tố dư thừa như căng thẳng không cần thiết, lịch trình quá tải, cam kết thiếu giá trị, chi tiêu không phù hợp, sự phân tán chú ý, kỳ vọng quá mức, so sánh xã hội và những hoạt động làm suy giảm khả năng phục hồi. MAP không mặc định rằng muốn sống tốt hơn luôn phải có thêm nguồn lực hoặc loại bỏ càng nhiều thứ càng tốt. Trong nhiều trường hợp, điều cần thiết là điều chỉnh tỷ lệ, cường độ, chất lượng, thời điểm hoặc cách phân bổ những gì đã có. Chẳng hạn, bạn có thể không cần làm việc ít hơn trong mọi hoàn cảnh mà cần giảm sự gián đoạn và tăng quyền chủ động; không nhất thiết cần thêm nhiều mối quan hệ mà cần tăng chất lượng kết nối; hoặc không cần thêm hoạt động giải trí mà cần cải thiện khả năng nghỉ ngơi thực sự. MAP đồng thời phân tích những sự phụ thuộc giữa yếu tố cần thêm và yếu tố cần bớt, bởi muốn có thêm thời gian cho gia đình có thể phải giảm một số cam kết, muốn tăng khả năng tập trung có thể cần giảm tác nhân gây xao nhãng, và muốn cải thiện sức khỏe có thể cần bổ sung hoạt động phục hồi đồng thời giảm những hành vi gây quá tải. Tuy nhiên, MAP không quy mọi khó khăn về lựa chọn cá nhân, bởi điều kiện tài chính, sức khỏe, trách nhiệm chăm sóc, môi trường lao động và những giới hạn xã hội có thể khiến việc bổ sung hoặc cắt giảm trở nên khó khăn. MAP cũng không xem sự thiếu hụt hoặc dư thừa là đặc điểm cố định; chúng có thể thay đổi theo từng giai đoạn sống. Từ đó, MAP giúp bạn xây dựng bản đồ nhu cầu và gánh nặng, xác định những điều cần thêm, cần bớt, cần giữ và cần thay đổi cách sử dụng; đánh giá lợi ích, chi phí và khả năng thực hiện; lựa chọn những điều chỉnh có tác động lớn nhưng phù hợp nguồn lực; qua đó chuyển từ việc cố gắng cải thiện mọi mặt cùng lúc sang chủ động tinh chỉnh cấu trúc cuộc sống để tạo ra nhiều giá trị hơn với mức tiêu hao hợp lý hơn.",
