    "groupTitle": "HẠNH PHÚC & CHẤT LƯỢNG SỐNG",
    "title": "PHIÊN BẢN CUỘC SỐNG CHẤT LƯỢNG CAO NHẤT PHÙ HỢP VỚI BẠN SẼ ĐƯỢC TỔ CHỨC NHƯ THẾ NÀO?",
    "subtitle": "MAP này tập trung xây dựng bản thiết kế tổng thể cho phiên bản cuộc sống có chất lượng cao nhất trong phạm vi phù hợp với giá trị, nhu cầu, năng lực, nguồn lực, hoàn cảnh và những giới hạn thực tế của bạn. Trọng tâm của MAP không phải là hình dung một cuộc sống hoàn hảo, sở hữu nhiều thành tựu nhất hoặc đáp ứng mọi tiêu chuẩn thành công, mà là xác định cách tổ chức cuộc sống giúp bạn đạt được mức độ hài lòng, sức khỏe, sự tự chủ, kết nối, ý nghĩa và khả năng phát triển tốt nhất có thể duy trì trong dài hạn. MAP phân biệt cuộc sống lý tưởng với cuộc sống khả thi, chất lượng sống cao với mức tiêu dùng cao, sự tối ưu với chủ nghĩa hoàn hảo, cấu trúc ổn định với lịch trình cứng nhắc, và một hệ thống sống hiệu quả với việc kiểm soát mọi hoạt động thường ngày. Đặc biệt, MAP xem xét cuộc sống như một hệ thống gồm nhiều thành phần liên kết: sức khỏe thể chất và tinh thần, công việc, tài chính, gia đình, quan hệ xã hội, môi trường sống, thời gian cá nhân, nghỉ ngơi, học hỏi, trải nghiệm, đóng góp và định hướng tương lai. Mỗi thành phần không được thiết kế riêng lẻ mà cần được tổ chức theo mối quan hệ tương hỗ, bởi một công việc có thu nhập tốt nhưng làm suy giảm sức khỏe có thể không phù hợp với mục tiêu chất lượng sống; một lịch trình nhiều hoạt động tích cực nhưng thiếu thời gian phục hồi cũng có thể trở nên quá tải; hoặc một cuộc sống ổn định nhưng không còn không gian cho khám phá có thể chưa đáp ứng nhu cầu phát triển. MAP phân tích cách xác định những điều kiện nền tảng không thể thiếu, lựa chọn các ưu tiên tạo giá trị lớn nhất, thiết lập mức đủ cho từng lĩnh vực, phân bổ thời gian và nguồn lực, tổ chức nhịp sống hằng ngày, xây dựng hệ thống hỗ trợ và xác lập giới hạn bảo vệ chất lượng sống. MAP đồng thời chú trọng khả năng thích nghi trước thay đổi về tuổi tác, sức khỏe, thu nhập, công việc, trách nhiệm gia đình và những biến động ngoài dự kiến. Một phiên bản sống chất lượng cao không nhất thiết có cùng hình thức ở mọi giai đoạn, cũng không thể được xác định bằng một công thức chung cho tất cả mọi người. MAP vì vậy không đưa ra lời hứa về một trạng thái hạnh phúc tối đa cố định, mà hướng đến thiết kế cấu trúc sống có tính khả thi, linh hoạt, được kiểm chứng bằng trải nghiệm thực tế và có thể điều chỉnh khi nhu cầu thay đổi. Từ đó, MAP giúp bạn chuyển những giá trị trừu tượng thành tiêu chuẩn thiết kế cụ thể, kết nối các mục tiêu riêng lẻ thành một hệ thống thống nhất, xác định những điều cần ưu tiên và bảo vệ, thiết lập cơ chế vận hành hằng ngày, xây dựng phương án dự phòng và đánh giá chất lượng sống định kỳ; qua đó chuyển từ việc cải thiện từng vấn đề riêng biệt sang chủ động kiến tạo một phiên bản cuộc sống phù hợp, cân bằng, có khả năng phục hồi và đáng sống theo tiêu chuẩn thực sự của bản thân.",
